`timescale 1ns/1ps

// Packs two consecutive RGB565 pixels into one 32-bit FIFO word.
// The earlier pixel occupies the upper half to match the big-endian
// asymmetric FIFO configuration generated by Efinity IP Manager.
module rgb565_pair_packer (
    input              clk,
    input              rst_n,
    input              sink_sop,
    input              sink_valid,
    input      [15:0]  sink_data,
    output reg         source_valid,
    output reg [31:0]  source_data
);

reg        first_pixel_pending;
reg [15:0] first_pixel_data;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        first_pixel_pending <= 1'b0;
        first_pixel_data    <= 16'd0;
        source_valid        <= 1'b0;
        source_data         <= 32'd0;
    end else begin
        source_valid <= 1'b0;

        if (sink_valid && sink_sop) begin
            first_pixel_pending <= 1'b1;
            first_pixel_data    <= sink_data;
        end else if (sink_valid && first_pixel_pending) begin
            first_pixel_pending <= 1'b0;
            source_valid        <= 1'b1;
            source_data         <= {first_pixel_data, sink_data};
        end else if (sink_valid) begin
            first_pixel_pending <= 1'b1;
            first_pixel_data    <= sink_data;
        end
    end
end

endmodule
